struct vector3d
{
  float x;
  float y;
  float z;

  vector3d() {}
  vector3d(float X, float Y, float Z) : x(X), y(Y), z(Z) {}
};

struct po
{
  float data[16];

  void set_position(const vector3d& position)
  {
    data[12] = position.x;
    data[13] = position.y;
    data[14] = position.z;
  }
};

struct entity_vtable
{
  char padding[1560];
  short set_render_scale_adjustment;
  short padding2;
  void (*set_render_scale)(void*, const vector3d&);
};

struct entity
{
  char padding[8];
  entity_vtable* vtable;

  void set_render_scale(const vector3d& scale)
  {
    vtable->set_render_scale(
      (char*)this + vtable->set_render_scale_adjustment, scale);
  }
};

extern const po po_identity_matrix;
extern const char position_name[];
extern const char velocity_name[];
extern const char scale_name[];
extern const char life_name[];
extern const char dont_rotate_name[];

__asm__(".equ po_identity_matrix,0x005545C0");
__asm__(".equ position_name,0x004D0AD8");
__asm__(".equ velocity_name,0x004D0AE8");
__asm__(".equ scale_name,0x004D0AF8");
__asm__(".equ life_name,0x004D0B00");
__asm__(".equ dont_rotate_name,0x004D0B08");

class beach_object
{
  char padding0[40];

protected:
  entity* my_entity;

private:
  char padding1[16];

public:
  bool parse_params(char** argp, int argc);
  bool find_param(char** argp, int argc, const char* name) const;
  bool read_float_param(
    char** argp, int argc, const char* name, float* value) const;
  bool read_vector3d_param(
    char** argp, int argc, const char* name, vector3d* value) const;
};

__asm__(".equ parse_params__12beach_objectPPci,0x001FAB80");
__asm__(".equ find_param__C12beach_objectPPciPCc,0x001FAC30");
__asm__(".equ read_float_param__C12beach_objectPPciPCcPf,0x001FAD50");
__asm__(".equ read_vector3d_param__C12beach_objectPPciPCcP8vector3d,0x001FADF8");

class beach_billboard : public beach_object
{
  vector3d my_velocity;
  char padding0[8];
  po my_initial_po;
  int rotate;
  float my_age;
  float my_life;

public:
  bool parse_params(char** argp, int argc);
};

bool beach_billboard::parse_params (char** argp, int argc)
{
  vector3d pos;
  float scale;

  if (!beach_object::parse_params (argp, argc))
    return false;

  if (!read_vector3d_param (argp, argc, position_name, &pos))
    return false;

  if (!read_vector3d_param (argp, argc, velocity_name, &my_velocity))
    return false;

  if (read_float_param (argp, argc, scale_name, &scale))
    my_entity->set_render_scale (vector3d (scale, scale, scale));

  read_float_param (argp, argc, life_name, &my_life);

  if (find_param (argp, argc, dont_rotate_name))
    rotate = false;

  my_initial_po = po_identity_matrix;
  my_initial_po.set_position (pos);

  return true;
}
